script.text:

function load$Grid$SaleBatch$Extra$(g) {
	g.add_commandEvent(on$Grid$SaleBatch$Extra$ExecuteCommand);
	g.add_itemValueChanged(onChange$Grid$SaleBatch$);
	g.$a = {
		chinh_sach : '[chinh_sach]:=([$ma_nh]+\'-\'+[ma_dot]+\'-CS\'+ (\'0\'+ this._activeRow).slice(-2)).toUpperCase()',
	}
	stateManagerFG(g);
}
function dispose$Grid$SaleBatch$Extra$(g) {
	try {g.remove_commandEvent(on$Grid$SaleBatch$Extra$ExecuteCommand);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$Grid$SaleBatch$);} catch (ex) {}
}
function on$Grid$SaleBatch$Extra$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {
		&Clipboard.Event.Before;
		&GridExtraToolbarExecuteCommandScript;
		case 'Check':
			if (f.getItemValue('loai_nh') != '1') {g._rowCount = 0;}
			break;
		default:
			break;
	}
}
function onChange$Grid$SaleBatch$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	switch (name) {
		case 'ma_dot':
			g.validExpression(o, [ g.$a.chinh_sach]);
			break;
		default:
			break;
	}
}
function onChange$ma_dot(o) {
	var g = o.grid;
	g.raiseItemValueChanged(new FastBusiness.AjaxControlExtender.ColumnEventArgs(o));
}

function stateManagerFG(g) {
	var f = g.get_element().parentForm;
	var mf = {}, exps = Object.entries(g.$a), match;
	var regexMasterField = /\[\$(\w+)\]/g;
	for (var i = 0; i<exps.length;i++) {
		var mfi = exps[i][1];
		while((match=regexMasterField.exec(mfi))) {
			var expLst = mf[match[1]];
			expLst = expLst ? expLst.push(exps[i][0]) : [exps[i][0]]
			mf[match[1]] = expLst;
		}
	}
	mf = Object.entries(mf);
	for (var i = 0;i<mf.length;i++) {
		var o = f.getItem(mf[i][0]), oexp = mf[i][1];
		var oldHandler = o.onchange;
		var exps = Object.entries(g.$a).filter(function(e) {return oexp.includes(e[0])}).map(function(e) {return e[1]});

		o.onchange = function(event) {
			if (typeof oldHandler === 'function') oldHandler.call(this, event);
			handleMasterFieldChange(this, exps, g);
		}
	}
}

function handleMasterFieldChange(o, exps, g) {
	if (exps.length==0 || !o || !g) return;
	for (var row = 1; row <= g._rowCount;row++) {
		var orow = g._getItem(row, 1);
		orow.row = row;
		g._setActiveCell(orow)
		g.validExpression(orow, exps);
	}
}


		&GridExtraToolbarScript;
